metadata.er-schema:
{
  "title": "looply · 营销活动（促销折扣）实体关系图",
  "version": "v1.1 · 2026-07-13",
  "tables": [
    {
      "name": "promotion",
      "comment": "营销活动",
      "columns": [
        {
          "name": "id",
          "comment": "活动ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_name",
          "comment": "活动名称",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 draft/active/ended",
          "constraint": ""
        },
        {
          "name": "start_at",
          "comment": "活动开始时间",
          "constraint": ""
        },
        {
          "name": "end_at",
          "comment": "活动结束时间（空=长期）",
          "constraint": ""
        },
        {
          "name": "created_by",
          "comment": "创建人",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "活动=分组容器。本期极简，活动维度聚合统计放后续迭代"
    },
    {
      "name": "promotion_rule",
      "comment": "折扣规则",
      "columns": [
        {
          "name": "id",
          "comment": "规则ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_id",
          "comment": "所属活动",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "rule_name",
          "comment": "规则名称（订单侧快照来源）",
          "constraint": ""
        },
        {
          "name": "trigger_type",
          "comment": "触发方式 auto自动/code优惠码",
          "constraint": ""
        },
        {
          "name": "discount_type",
          "comment": "折扣类型 product商品/order订单",
          "constraint": ""
        },
        {
          "name": "value_type",
          "comment": "折扣值类型 percentage百分比/fixed固定金额",
          "constraint": ""
        },
        {
          "name": "percentage_value",
          "comment": "百分比值（value_type=percentage用，全市场统一）",
          "constraint": ""
        },
        {
          "name": "product_scope",
          "comment": "商品范围 all/category/brand/listing（仅商品折扣）",
          "constraint": ""
        },
        {
          "name": "min_type",
          "comment": "门槛类型 none无/amount满额/quantity满件",
          "constraint": ""
        },
        {
          "name": "min_quantity",
          "comment": "满件门槛值（min_type=quantity用）",
          "constraint": ""
        },
        {
          "name": "max_item_count",
          "comment": "每单最多作用件数（商品折扣可选封顶）",
          "constraint": ""
        },
        {
          "name": "total_usage_limit",
          "comment": "总使用次数上限（空=不限）",
          "constraint": ""
        },
        {
          "name": "per_user_limit",
          "comment": "每人使用次数上限（空=不限）",
          "constraint": ""
        },
        {
          "name": "used_count",
          "comment": "已核销次数（冗余计数，用尽即停）",
          "constraint": ""
        },
        {
          "name": "combines_with",
          "comment": "可叠加折扣类【V2预留】",
          "constraint": ""
        },
        {
          "name": "eligibility",
          "comment": "适用人群 all全部【人群定向V2预留】",
          "constraint": ""
        },
        {
          "name": "budget_total",
          "comment": "规则预算总额【V2预留】",
          "constraint": ""
        },
        {
          "name": "budget_spent",
          "comment": "已消耗预算【V2预留】",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/paused",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "聚合根。规则真正载体；trigger_type=auto无码/code绑码；金额预算池/人群定向为V2预留"
    },
    {
      "name": "promotion_market",
      "comment": "规则-市场明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "投放市场ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "currency_code",
          "comment": "币种（录值口径）",
          "constraint": ""
        },
        {
          "name": "fixed_amount",
          "comment": "固定金额折扣值（value_type=fixed用）",
          "constraint": ""
        },
        {
          "name": "min_amount",
          "comment": "满额门槛值（min_type=amount用，按币种）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "双职责：①投放市场范围 ②固定金额/满额门槛按币种录值，无实时汇率"
    },
    {
      "name": "promotion_target",
      "comment": "规则商品范围明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_type",
          "comment": "圈选类型 category品类/brand品牌/listing指定商品",
          "constraint": ""
        },
        {
          "name": "target_id",
          "comment": "目标ID（对应category_id/brand_id/listing_id）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "仅商品折扣使用；product_scope=all 时无记录"
    },
    {
      "name": "promotion_code",
      "comment": "优惠码",
      "columns": [
        {
          "name": "id",
          "comment": "优惠码ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "code",
          "comment": "优惠码字符串",
          "constraint": "UNIQUE"
        },
        {
          "name": "status",
          "comment": "状态 active/disabled",
          "constraint": ""
        },
        {
          "name": "used_count",
          "comment": "该码已使用次数（冗余计数）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "仅 trigger_type=code 使用；一规则可多码做定向发放"
    },
    {
      "name": "promotion_redemption",
      "comment": "核销流水",
      "columns": [
        {
          "name": "id",
          "comment": "核销ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "rule_id",
          "comment": "规则ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "code_id",
          "comment": "优惠码ID（自动折扣为空）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "redeemed_at",
          "comment": "核销时间",
          "constraint": ""
        }
      ],
      "note": "仅计数不记金额（金额归订单 order_discount）。判限次：总量看规则used_count、每人看(rule,user)、码级看code_id"
    },
    {
      "name": "ref_product",
      "comment": "商品域（引用）",
      "columns": [
        {
          "name": "listing_id",
          "comment": "在售商品ID",
          "constraint": ""
        },
        {
          "name": "spu_id",
          "comment": "SPU ID",
          "constraint": ""
        },
        {
          "name": "category_id",
          "comment": "品类ID",
          "constraint": ""
        },
        {
          "name": "brand_id",
          "comment": "品牌ID",
          "constraint": ""
        }
      ],
      "note": "圈选活动商品时只读；商品折扣命中维度"
    },
    {
      "name": "ref_market",
      "comment": "market（引用）",
      "columns": [
        {
          "name": "market_id",
          "comment": "市场ID",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        }
      ],
      "note": "规则投放市场、币种口径来源"
    },
    {
      "name": "ref_user",
      "comment": "用户（引用）",
      "columns": [
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": ""
        }
      ],
      "note": "核销归属用户，每人限次判定"
    },
    {
      "name": "ref_order",
      "comment": "订单-优惠记录（引用）",
      "columns": [
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": ""
        },
        {
          "name": "promotion_ref_id",
          "comment": "促销规则ID（指向rule）",
          "constraint": ""
        },
        {
          "name": "discount_amount",
          "comment": "优惠金额（订单模块管）",
          "constraint": ""
        }
      ],
      "note": "order_discount.promotion_ref_id → promotion_rule.id；金额明细归订单模块"
    }
  ],
  "relations": [
    {
      "from": "promotion_rule",
      "to": "promotion",
      "type": "N:1",
      "label": "归属活动",
      "penwidth": 1.6
    },
    {
      "from": "promotion_market",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "投放市场",
      "penwidth": 1.4
    },
    {
      "from": "promotion_target",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "圈选商品"
    },
    {
      "from": "promotion_code",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "优惠码",
      "penwidth": 1.4
    },
    {
      "from": "promotion_redemption",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "核销",
      "penwidth": 1.4
    },
    {
      "from": "promotion_redemption",
      "to": "promotion_code",
      "type": "N:1",
      "label": "码核销"
    },
    {
      "from": "promotion_market",
      "to": "ref_market",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_target",
      "to": "ref_product",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "ref_user",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "ref_order",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "ref_order",
      "to": "promotion_rule",
      "type": "N:1",
      "label": "规则快照引用",
      "color": "#9AA0A6",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "活动-规则-码三层": "活动=分组容器；折扣规则=规则真正载体(聚合根)；优惠码=有码触发凭证。一活动多规则、一规则多码",
    "触发方式": "promotion_rule.trigger_type=auto时无码自动生效；=code时挂1~N个promotion_code由用户输码触发",
    "金额不重复建": "营销只管规则与核销计数；每单实际让利金额与行级分摊归订单模块 order_discount / order_discount_item",
    "订单侧契约": "order_discount.promotion_ref_id 指向 promotion_rule.id，promotion_name 存 rule_name 快照",
    "多币种录值": "固定金额折扣值与满额门槛按 promotion_market 逐市场币种录入，无实时汇率换算；百分比值全市场统一",
    "用量控制": "总次数看 rule.used_count、每人次数看(rule_id,user_id)计数、码级看 code_id、有效期看活动 start_at/end_at",
    "互斥取优_V1": "同一订单多规则命中时取对用户最优的一个；combines_with 预留 Shopify 组合类模型，V2 放开叠加",
    "V2预留": "budget_total/budget_spent(金额预算池)、阶梯门槛、eligibility(人群定向)、活动维度聚合统计 均本版不落逻辑",
    "范围_V1": "仅平台运营创建；折扣成本默认平台承担；三方商家自主营销为后续版本"
  }
}
